// The CLI `minispec` of the `minispec` slice. The launcher `bin/minispec` calls `main`.
//
//   minispec new <name> [--tier medium|big|large] [--capability <name>]
//   minispec list [--specs] | show <name> | status [<name>] | validate [<name>] | archive <name> [--yes]
//
// The files are in `minispec/` at the project root: the folder that has `minispec/`, or else the root of the git checkout or linked worktree.
// A linked worktree has `.git` as a file, so the walk up finds its own root and needs no clean main checkout.
// The output is for a person, or JSON with `--json`. The result goes to stdout, and the messages and errors go to stderr.
// Exit status: 0 on success, 1 on a failure, 2 on a usage fault.
// The CLI keeps no log and asks nothing, so it reads no answer in a language (<https://clig.dev/>).

import fs from "node:fs/promises";
import path from "node:path";
import { ABSENT, rethrowUnless } from "../../../kernel/errors.ts";
import { fileReader } from "../../../kernel/node/fs.ts";
import type { Context, Store } from "../domain/types.ts";
import { MINISPEC_DIR } from "../limits.ts";
import { run } from "./run.ts";

const exists = async (file: string): Promise<boolean> => {
  try {
    await fs.stat(file);
    return true;
  } catch (err) {
    rethrowUnless(err, ...ABSENT);
    return false;
  }
};

/** The store on the disk. A write makes its folders. */
export const diskStore: Store = {
  read: fileReader.read,
  list: fileReader.list,
  write: async (file, text) => void (await Bun.write(file, text)),
  exists,
  move: async (from, to) => {
    await fs.mkdir(path.dirname(to), { recursive: true });
    await fs.rename(from, to);
  },
};

/** The project root: the nearest folder above `cwd` (or `cwd`) that has `minispec/` or `.git`, else `cwd`. */
export const findRoot = async (cwd: string, store: Store): Promise<string> => {
  for (let dir = cwd; ; dir = path.dirname(dir)) {
    if (
      (await store.exists(path.join(dir, MINISPEC_DIR))) ||
      (await store.exists(path.join(dir, ".git")))
    )
      return dir;
    if (path.dirname(dir) === dir) return cwd;
  }
};

/** The local date of `now` as `YYYY-MM-DD`, because a person reads the archive folder name as their own date. */
export const localDate = (now: Date): string =>
  [
    String(now.getFullYear()).padStart(4, "0"),
    String(now.getMonth() + 1).padStart(2, "0"),
    String(now.getDate()).padStart(2, "0"),
  ].join("-");

const context = async (cwd: string): Promise<Context> => ({
  store: diskStore,
  root: await findRoot(cwd, diskStore),
  today: localDate(new Date()),
});

/** Run the CLI with `args` and return the exit status. */
export const main = async (
  args: string[],
  cwd: string = process.cwd(),
): Promise<number> => {
  const reply = await run(args, () => context(cwd), {
    stdout: Boolean(process.stdout.isTTY),
    stderr: Boolean(process.stderr.isTTY),
    noColorEnv: process.env["NO_COLOR"],
  });
  if (reply.out) console.log(reply.out);
  if (reply.err) console.error(reply.err);
  return reply.code;
};
